  1→import { useState, useCallback, useEffect } from "react";
  2→import type {
  3→  ActionFunctionArgs,
  4→  HeadersFunction,
  5→  LoaderFunctionArgs,
  6→} from "react-router";
  7→import { useFetcher, useLoaderData, useNavigate, useRouteError } from "react-router";
  8→import { useAppBridge } from "@shopify/app-bridge-react";
  9→import { authenticate } from "../shopify.server";
 10→import { boundary } from "@shopify/shopify-app-react-router/server";
 11→import db from "../db.server";
 12→import { getShopSubscription } from "../billing.server";
 13→import { PLAN_LIMITS } from "../plans";
 14→import type { PlanTier } from "../plans";
 15→import {
 16→  Page,
 17→  Layout,
 18→  Card,
 19→  BlockStack,
 20→  InlineStack,
 21→  InlineGrid,
 22→  Text,
 23→  Button,
 24→  TextField,
 25→  Select,
 26→  Checkbox,
 27→  Divider,
 28→  Box,
 29→  Banner,
 30→  Badge,
 31→  Modal,
 32→} from "@shopify/polaris";
 33→
 34→export const loader = async ({ request }: LoaderFunctionArgs) => {
 35→  const { session, admin } = await authenticate.admin(request);
 36→  const shop = session.shop;
 37→
 38→  let config = await db.widgetConfig.findUnique({ where: { shop } });
 39→
 40→  if (!config) {
 41→    config = await db.widgetConfig.create({ data: { shop } });
 42→  }
 43→
 44→  const subscription = await getShopSubscription(shop);
 45→
 46→  return { config, subscription };
 47→};
 48→
 49→// Helper: sync widget config to an App Installation metafield so the
 50→// storefront Liquid block can read it via app.metafields.zip_checker.widget_config.value
 51→//
 52→// IMPORTANT: ownerId MUST be the App Installation GID (not the Shop GID).
 53→// app.metafields in Liquid only surfaces metafields owned by the App Installation.
 54→// Using the Shop GID writes to shop metafields which are invisible to app.metafields.
 55→async function syncConfigMetafield(
 56→  admin: Awaited<ReturnType<typeof authenticate.admin>>["admin"],
 57→  configData: Record<string, unknown>,
 58→) {
 59→  try {
 60→    // Step 1: get the App Installation GID
 61→    const installResponse = await admin.graphql(
 62→      `query { currentAppInstallation { id } }`,
 63→    );
 64→    const installJson = (await installResponse.json()) as {
 65→      data: { currentAppInstallation: { id: string } };
 66→    };
 67→    const appInstallationGid = installJson.data.currentAppInstallation.id;
 68→
 69→    // Step 2: write the metafield to the App Installation
 70→    // Namespace must be plain "zip_checker" (no "$app:" prefix) for App Installation metafields.
 71→    // The Liquid block reads: app.metafields.zip_checker.widget_config.value
 72→    const metaResponse = await admin.graphql(
 73→      `mutation MetafieldsSet($metafields: [MetafieldsSetInput!]!) {
 74→        metafieldsSet(metafields: $metafields) {
 75→          metafields { id namespace key }
 76→          userErrors { field message }
 77→        }
 78→      }`,
 79→      {
 80→        variables: {
 81→          metafields: [
 82→            {
 83→              ownerId: appInstallationGid,
 84→              namespace: "zip_checker",
 85→              key: "widget_config",
 86→              type: "json",
 87→              value: JSON.stringify(configData),
 88→            },
 89→          ],
 90→        },
 91→      },
 92→    );
 93→    const metaJson = (await metaResponse.json()) as {
 94→      data: {
 95→        metafieldsSet: {
 96→          metafields: { id: string; namespace: string; key: string }[];
 97→          userErrors: { field: string; message: string }[];
 98→        };
 99→      };
100→    };

100→    };
101→
102→    // userErrors are non-fatal — the API fallback still works
103→  } catch {
104→    // Non-fatal — the API fallback still works
105→  }
106→}
107→
108→export const action = async ({ request }: ActionFunctionArgs) => {
109→  const { session, admin } = await authenticate.admin(request);
110→  const shop = session.shop;
111→  const formData = await request.formData();
112→  const intent = formData.get("intent");
113→
114→  if (intent === "save") {
115→    const data = {
116→      position: String(formData.get("position") || "inline"),
117→      primaryColor: String(formData.get("primaryColor") || "#008060"),
118→      successColor: String(formData.get("successColor") || "#008060"),
119→      errorColor: String(formData.get("errorColor") || "#D72C0D"),
120→      backgroundColor: String(formData.get("backgroundColor") || "#FFFFFF"),
121→      textColor: String(formData.get("textColor") || "#202223"),
122→      heading: String(formData.get("heading") || "Check Delivery Availability"),
123→      placeholder: String(formData.get("placeholder") || "Enter your zip code"),
124→      buttonText: String(formData.get("buttonText") || "Check"),
125→      successMessage: String(
126→        formData.get("successMessage") ||
127→          "Great news! We deliver to your area.",
128→      ),
129→      errorMessage: String(
130→        formData.get("errorMessage") ||
131→          "Sorry, we don't deliver to this area yet.",
132→      ),
133→      notFoundMessage: String(
134→        formData.get("notFoundMessage") ||
135→          "We currently do not ship to this ZIP code.",
136→      ),
137→      showEta: formData.get("showEta") === "true",
138→      showZone: formData.get("showZone") === "true",
139→      showWaitlistOnFailure: formData.get("showWaitlistOnFailure") === "true",
140→      showCod: formData.get("showCod") === "true",
141→      showReturnPolicy: formData.get("showReturnPolicy") === "true",
142→      showCutoffTime: formData.get("showCutoffTime") === "true",
143→      showDeliveryDays: formData.get("showDeliveryDays") === "true",
144→      blockCartOnInvalid: formData.get("blockCartOnInvalid") === "true",
145→      blockCheckoutInCart: formData.get("blockCheckoutInCart") === "true",
146→      showSocialProof: formData.get("showSocialProof") === "true",
147→      borderRadius: String(formData.get("borderRadius") || "8"),
148→      widgetStyle: String(formData.get("widgetStyle") || "minimal"),
149→      customCss: String(formData.get("customCss") || "") || null,
150→    };
151→
152→    await db.widgetConfig.upsert({
153→      where: { shop },
154→      create: { shop, ...data },
155→      update: data,
156→    });
157→
158→    await syncConfigMetafield(admin, data);
159→
160→    return { success: true };
161→  }
162→
163→  if (intent === "reset") {
164→    const resetData = {
165→      position: "inline",
166→      primaryColor: "#008060",
167→      successColor: "#008060",
168→      errorColor: "#D72C0D",
169→      backgroundColor: "#FFFFFF",
170→      textColor: "#202223",
171→      heading: "Check Delivery Availability",
172→      placeholder: "Enter your zip code",
173→      buttonText: "Check",
174→      successMessage: "Great news! We deliver to your area.",
175→      errorMessage: "Sorry, we don't deliver to this area yet.",
176→      notFoundMessage: "We currently do not ship to this ZIP code.",
177→      showEta: true,
178→      showZone: false,
179→      showWaitlistOnFailure: false,
180→      showCod: true,
