              </div>
              <div className="zcc-search-bar">
                <input
                  className="zcc-input"
                  type="text"
                  placeholder={cfg.placeholder}
                  readOnly
                />
                <button className="zcc-btn" type="button">
                  {searchIcon}
                  {cfg.buttonText}
                </button>
              </div>
            </div>
            <button
              type="button"
              style={{
                background: cfg.primaryColor,
                color: "#fff",
                border: "none",
                borderRadius: "50px",
                padding: "12px 20px",
                fontSize: "14px",
