                            width: "36px",
                            height: "36px",
                            border: "2px solid var(--p-color-border-secondary)",
                            borderRadius: "var(--p-border-radius-200)",
                            cursor: limits.widgetFullCustom ? "pointer" : "not-allowed",
                            padding: "2px",
                            opacity: limits.widgetFullCustom ? 1 : 0.5,
                          }}
